import { createSlice, createAsyncThunk, PayloadAction } from '@reduxjs/toolkit';
import { fetchNews } from '../services/newsService';

export const fetchArticles = createAsyncThunk(
    'news/fetchArticles',
    async ({ query, source, date, category, author }: { query: string; source: string; date: string; category: string; author: string }) => {
      const data = await fetchNews(query, source, date, category, author);

      let articles = data.articles || data.response?.docs || data.response?.results;

      // ✅ Manually filter articles if the API doesn't support author filtering
      if (author) {
        articles = articles.filter((article: any) =>
          (article.author?.toLowerCase() === author.toLowerCase()) || 
          (article.byline?.original?.toLowerCase() === author.toLowerCase()) ||
          (article.fields?.byline?.toLowerCase() === author.toLowerCase())
        );
      }

      return { articles, source, date, category, author };
    }
  );

const newsSlice = createSlice({
  name: 'news',
  initialState: { articles: [], status: 'idle', source: 'newsapi', date: '', category: '', author: '' },
  reducers: {
    setFilters: (state, action: PayloadAction<{ date: string; category: string; author: string }>) => {
      state.date = action.payload.date;
      state.category = action.payload.category;
      state.author = action.payload.author;
    },
  },
  extraReducers: (builder) => {
    builder
      .addCase(fetchArticles.pending, (state) => { state.status = 'loading'; })
      .addCase(fetchArticles.fulfilled, (state, action) => {
        state.status = 'succeeded';
        state.articles = action.payload.articles;
        state.source = action.payload.source;
        state.date = action.payload.date;
        state.category = action.payload.category;
        state.author = action.payload.author;
      })
      .addCase(fetchArticles.rejected, (state) => { state.status = 'failed'; });
  },
});

export const { setFilters } = newsSlice.actions;
export default newsSlice.reducer;
